// Compare what HubSpot links now with what Simpro says it should link.
// Links that match are left alone; stale ones are removed; missing ones are added.
const fromId = String($('Upsert Site in HubSpot').first().json.id);
const current = new Set(($('Get Site-Company Associations').first().json.results ?? []).map(r => String(r.toObjectId)));
const desired = new Set((($('Get Simpro Site').first().json.Customers ?? []).length ? $input.all().map(i => i.json.id) : [])
  .filter(v => v !== undefined && v !== null && v !== '')
  .map(String));

const remove = [...current].filter(id => !desired.has(id));
const add = [...desired].filter(id => !current.has(id));

const out = [];
if (remove.length) out.push({ json: { action: 'remove', ids: remove,
  body: { inputs: [{ from: { id: fromId }, to: remove.map(id => ({ id })) }] } } });
if (add.length) out.push({ json: { action: 'add', ids: add,
  body: { inputs: add.map(id => ({ from: { id: fromId }, to: { id } })) } } });
return out; // empty = already in sync, nothing to do

